import { tags } from "typia";

/**
 * Author information for economic discussion articles, providing attribution
 * and credibility context for content discovery. Supports both member and
 * moderator authors within the community platform with proper type
 * discrimination.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IEconomicDiscussionArticleAuthor = {
  /**
   * Unique identifier for the author in their respective user table
   * (economic_discussion_members or economic_discussion_moderators).
   */
  id: string & tags.Format<"uuid">;

  /**
   * Display name used by this author when participating in community
   * discussions.
   */
  username: string &
    tags.MinLength<3> &
    tags.MaxLength<30> &
    tags.Pattern<"^[a-zA-Z0-9_-]{3,30}$">;

  /**
   * Author type indicating whether this article was written by a community
   * member or moderator. Value is determined by which foreign key field
   * (economic_discussion_member_id or economic_discussion_moderator_id) is
   * populated in the article record.
   */
  type: "member" | "moderator";

  /**
   * Community participation score based on user activity and engagement
   * quality within the economic discussion community. For members, this
   * reflects their contribution history. For moderators, this reflects their
   * administrative activity and community management effectiveness.
   */
  reputation_score: number & tags.Type<"int32"> & tags.Minimum<0>;
};
